-- Audit question set 3 (22 Oct 2026, Francesco: "SOP timings, split the double questions, how long the food took,
-- dessert / coffee, name used, dish scores count in the food %"). Applied to the Kitchen DB on 22 Oct 2026.
-- Each audit keeps the set it started with (audit_visits.qset); a question shows when since_qset <= set and
-- (until_qset is null or set < until_qset). The page speaks qset 3 only on FOH DEV until it is pushed to LIVE.
alter table audit_visits add column if not exists qset int not null default 2;
alter table audit_catalog add column if not exists since_qset int not null default 1, add column if not exists until_qset int;
update audit_catalog set since_qset = 2 where code in ('srv.name','srv.person','srv.knowledge','srv.manager','sc.cigarsel');
update audit_catalog set until_qset = 2 where code = 'rt.knowledge';
update audit_catalog set position = position * 10;   -- run once: room to insert between questions

-- Set 3 retires these (they stay for audits under set 1 / 2)
update audit_catalog set until_qset = 3 where code in ('pre.greet','pre.occasion','pre.ready','ra.door','ra.walk','rt.bread','rt.pace','rt.mood','sc.mood','sc.firstdrink');

